class MagixCalendar{constructor(t){this.container=document.getElementById(t.containerId),this.titleElement=document.getElementById(t.titleId),this.year=t.currentYear,this.month=t.currentMonth,this.events=t.events||[],this.lang=t.lang||"fr",this.baseUrl=window.location.pathname}init(){this.render(),this.bindEvents()}bindEvents(){document.getElementById("prev-month").addEventListener("click",(()=>this.changeMonth(-1))),document.getElementById("next-month").addEventListener("click",(()=>this.changeMonth(1))),document.getElementById("today-btn").addEventListener("click",(()=>{const t=new Date;this.fetchMonth(t.getFullYear(),t.getMonth()+1)}))}async changeMonth(t){let e=this.month+t,n=this.year;e<1?(e=12,n--):e>12&&(e=1,n++),await this.fetchMonth(n,e)}async fetchMonth(t,e){try{const n=await fetch(`${this.baseUrl}?ajax=1&year=${t}&month=${e}`),s=await n.json();this.year=s.year,this.month=s.month,this.events=s.events,this.render(),this.updateURL()}catch(t){console.error("Erreur lors du chargement du calendrier :",t)}}render(){console.log("Mes évènements reçus :",this.events);const t=new Date(this.year,this.month-1);this.titleElement.innerText=t.toLocaleString(this.lang,{month:"long",year:"numeric"});const e=new Date(this.year,this.month-1,1).getDay(),n=(0===e?7:e)-1,s=new Date(this.year,this.month,0).getDate();let a="";for(let t=0;t<n;t++)a+='<div class="calendar-day bg-light text-muted"></div>';for(let t=1;t<=s;t++){const e=`${this.year}-${String(this.month).padStart(2,"0")}-${String(t).padStart(2,"0")}`,n=this.events.filter((t=>t.date_start.startsWith(e)));a+=`\n                <div class="calendar-day border ${n.length>0?"has-event":""}">\n                    <div class="fw-bold small mb-1">${t}</div>\n                    <div class="events-container">\n                        ${n.map((t=>`\n                            <a href="${t.slug}" class="event-link">\n                                ${t.title}\n                            </a>\n                        `)).join("")}\n                    </div>\n                </div>\n            `}this.container.innerHTML=a}updateURL(){const t=`${this.baseUrl}?year=${this.year}&month=${this.month}`;window.history.pushState({path:t},"",t)}}